        i61 = 3'b010; #1;
        if (o61 !== 2'b01) begin errors = errors + 1; $display("FA_X1 010: got %b", o61); end
        i61 = 3'b110; #1;
        if (o61 !== 2'b10) begin errors = errors + 1; $display("FA_X1 011: got %b", o61); end
        i61 = 3'b001; #1;
        if (o61 !== 2'b01) begin errors = errors + 1; $display("FA_X1 100: got %b", o61); end
        i61 = 3'b101; #1;
        if (o61 !== 2'b10) begin errors = errors + 1; $display("FA_X1 101: got %b", o61); end
        i61 = 3'b011; #1;
        if (o61 !== 2'b10) begin errors = errors + 1; $display("FA_X1 110: got %b", o61); end
        i61 = 3'b111; #1;
        if (o61 !== 2'b11) begin errors = errors + 1; $display("FA_X1 111: got %b", o61); end
        cells = cells + 1;
        i62 = 2'b00; #1;
        if (o62 !== 1'bz) begin errors = errors + 1; $display("TBUF_X1 00: got %b", o62); end
        i62 = 2'b10; #1;
        if (o62 !== 1'b0) begin errors = errors + 1; $display("TBUF_X1 01: got %b", o62); end
        i62 = 2'b01; #1;
        if (o62 !== 1'bz) begin errors = errors + 1; $display("TBUF_X1 10: got %b", o62); end
        i62 = 2'b11; #1;
        if (o62 !== 1'b1) begin errors = errors + 1; $display("TBUF_X1 11: got %b", o62); end
        cells = cells + 1;
        i63 = 2'b00; #1;
        if (o63 !== 1'bz) begin errors = errors + 1; $display("TBUF_X2 00: got %b", o63); end
        i63 = 2'b10; #1;
        if (o63 !== 1'b0) begin errors = errors + 1; $display("TBUF_X2 01: got %b", o63); end
        i63 = 2'b01; #1;
        if (o63 !== 1'bz) begin errors = errors + 1; $display("TBUF_X2 10: got %b", o63); end
        i63 = 2'b11; #1;
        if (o63 !== 1'b1) begin errors = errors + 1; $display("TBUF_X2 11: got %b", o63); end
        cells = cells + 1;
        #1;
        if (o64 !== 1'b0) begin errors = errors + 1; $display("TIE0 : got %b", o64); end
        cells = cells + 1;
        #1;
        if (o65 !== 1'b1) begin errors = errors + 1; $display("TIE1 : got %b", o65); end
        mx_a = 1; mx_s = 1'bx; #1;
        if (mx_y !== 1'b1) begin errors = errors + 1; $display("MUX2 with S=x: %b", mx_y); end
        // ---- flops: capture, hold, scan, enable, asynchronous clear and preset
        d = 1; se = 0; si = 0; e = 1; rn = 1; sn = 1; tick;
        cells = cells + 1; chk(s0_q, 1'b1, "DFF_X1 capture 1"); chk(s0_qn, 1'b0, "DFF_X1 QN");
        cells = cells + 1; chk(s1_q, 1'b1, "DFF_X2 capture 1"); chk(s1_qn, 1'b0, "DFF_X2 QN");
        cells = cells + 1; chk(s2_q, 1'b1, "DFFR_X1 capture 1"); chk(s2_qn, 1'b0, "DFFR_X1 QN");
        cells = cells + 1; chk(s3_q, 1'b1, "DFFR_X2 capture 1"); chk(s3_qn, 1'b0, "DFFR_X2 QN");
        cells = cells + 1; chk(s4_q, 1'b1, "DFFS_X1 capture 1"); chk(s4_qn, 1'b0, "DFFS_X1 QN");
        cells = cells + 1; chk(s5_q, 1'b1, "DFFS_X2 capture 1"); chk(s5_qn, 1'b0, "DFFS_X2 QN");
        cells = cells + 1; chk(s6_q, 1'b1, "DFFRS_X1 capture 1"); chk(s6_qn, 1'b0, "DFFRS_X1 QN");
        cells = cells + 1; chk(s7_q, 1'b1, "DFFE_X1 capture 1"); chk(s7_qn, 1'b0, "DFFE_X1 QN");
        cells = cells + 1; chk(s8_q, 1'b1, "SDFF_X1 capture 1"); chk(s8_qn, 1'b0, "SDFF_X1 QN");
        cells = cells + 1; chk(s9_q, 1'b1, "SDFF_X2 capture 1"); chk(s9_qn, 1'b0, "SDFF_X2 QN");
        cells = cells + 1; chk(s10_q, 1'b1, "SDFFR_X1 capture 1"); chk(s10_qn, 1'b0, "SDFFR_X1 QN");
        cells = cells + 1; chk(s11_q, 1'b1, "SDFFR_X2 capture 1"); chk(s11_qn, 1'b0, "SDFFR_X2 QN");
        cells = cells + 1; chk(s12_q, 1'b1, "SDFFS_X1 capture 1"); chk(s12_qn, 1'b0, "SDFFS_X1 QN");
        d = 0; tick;
        chk(s0_q, 1'b0, "DFF_X1 capture 0"); chk(s0_qn, 1'b1, "DFF_X1 QN");
        chk(s1_q, 1'b0, "DFF_X2 capture 0"); chk(s1_qn, 1'b1, "DFF_X2 QN");
        chk(s2_q, 1'b0, "DFFR_X1 capture 0"); chk(s2_qn, 1'b1, "DFFR_X1 QN");
        chk(s3_q, 1'b0, "DFFR_X2 capture 0"); chk(s3_qn, 1'b1, "DFFR_X2 QN");
        chk(s4_q, 1'b0, "DFFS_X1 capture 0"); chk(s4_qn, 1'b1, "DFFS_X1 QN");
        chk(s5_q, 1'b0, "DFFS_X2 capture 0"); chk(s5_qn, 1'b1, "DFFS_X2 QN");
        chk(s6_q, 1'b0, "DFFRS_X1 capture 0"); chk(s6_qn, 1'b1, "DFFRS_X1 QN");
        chk(s7_q, 1'b0, "DFFE_X1 capture 0"); chk(s7_qn, 1'b1, "DFFE_X1 QN");
        chk(s8_q, 1'b0, "SDFF_X1 capture 0"); chk(s8_qn, 1'b1, "SDFF_X1 QN");
        chk(s9_q, 1'b0, "SDFF_X2 capture 0"); chk(s9_qn, 1'b1, "SDFF_X2 QN");
        chk(s10_q, 1'b0, "SDFFR_X1 capture 0"); chk(s10_qn, 1'b1, "SDFFR_X1 QN");
        chk(s11_q, 1'b0, "SDFFR_X2 capture 0"); chk(s11_qn, 1'b1, "SDFFR_X2 QN");
        chk(s12_q, 1'b0, "SDFFS_X1 capture 0"); chk(s12_qn, 1'b1, "SDFFS_X1 QN");
        d = 1; #1;   // no clock edge: nothing moves
        chk(s0_q, 1'b0, "DFF_X1 holds");
        chk(s1_q, 1'b0, "DFF_X2 holds");
        chk(s2_q, 1'b0, "DFFR_X1 holds");
        chk(s3_q, 1'b0, "DFFR_X2 holds");
        chk(s4_q, 1'b0, "DFFS_X1 holds");
        chk(s5_q, 1'b0, "DFFS_X2 holds");
        chk(s6_q, 1'b0, "DFFRS_X1 holds");
        chk(s7_q, 1'b0, "DFFE_X1 holds");
        chk(s8_q, 1'b0, "SDFF_X1 holds");
        chk(s9_q, 1'b0, "SDFF_X2 holds");
        chk(s10_q, 1'b0, "SDFFR_X1 holds");
        chk(s11_q, 1'b0, "SDFFR_X2 holds");
        chk(s12_q, 1'b0, "SDFFS_X1 holds");
        d = 0; se = 1; si = 1; tick;   // scan shifts SI in
        chk(s0_q, 1'b0, "DFF_X1 scan");
        chk(s1_q, 1'b0, "DFF_X2 scan");
        chk(s2_q, 1'b0, "DFFR_X1 scan");
        chk(s3_q, 1'b0, "DFFR_X2 scan");
        chk(s4_q, 1'b0, "DFFS_X1 scan");
        chk(s5_q, 1'b0, "DFFS_X2 scan");
        chk(s6_q, 1'b0, "DFFRS_X1 scan");
        chk(s7_q, 1'b0, "DFFE_X1 scan");
        chk(s8_q, 1'b1, "SDFF_X1 scan");
        chk(s9_q, 1'b1, "SDFF_X2 scan");
        chk(s10_q, 1'b1, "SDFFR_X1 scan");
        chk(s11_q, 1'b1, "SDFFR_X2 scan");
        chk(s12_q, 1'b1, "SDFFS_X1 scan");
        se = 0; si = 0; d = 1; e = 0; tick;   // enable low keeps the value
        chk(s0_q, 1'b1, "DFF_X1 enable");
        chk(s1_q, 1'b1, "DFF_X2 enable");
        chk(s2_q, 1'b1, "DFFR_X1 enable");
        chk(s3_q, 1'b1, "DFFR_X2 enable");
        chk(s4_q, 1'b1, "DFFS_X1 enable");
        chk(s5_q, 1'b1, "DFFS_X2 enable");
        chk(s6_q, 1'b1, "DFFRS_X1 enable");
        chk(s7_q, 1'b0, "DFFE_X1 enable");
        chk(s8_q, 1'b1, "SDFF_X1 enable");
        chk(s9_q, 1'b1, "SDFF_X2 enable");
        chk(s10_q, 1'b1, "SDFFR_X1 enable");
        chk(s11_q, 1'b1, "SDFFR_X2 enable");
        chk(s12_q, 1'b1, "SDFFS_X1 enable");
        e = 1; d = 1; tick; rn = 0; #1;   // clear without a clock
        chk(s0_q, 1'b1, "DFF_X1 clear"); chk(s0_qn, 1'b0, "DFF_X1 clear QN");
        chk(s1_q, 1'b1, "DFF_X2 clear"); chk(s1_qn, 1'b0, "DFF_X2 clear QN");
        chk(s2_q, 1'b0, "DFFR_X1 clear"); chk(s2_qn, 1'b1, "DFFR_X1 clear QN");
        chk(s3_q, 1'b0, "DFFR_X2 clear"); chk(s3_qn, 1'b1, "DFFR_X2 clear QN");
        chk(s4_q, 1'b1, "DFFS_X1 clear"); chk(s4_qn, 1'b0, "DFFS_X1 clear QN");
        chk(s5_q, 1'b1, "DFFS_X2 clear"); chk(s5_qn, 1'b0, "DFFS_X2 clear QN");
        chk(s6_q, 1'b0, "DFFRS_X1 clear"); chk(s6_qn, 1'b1, "DFFRS_X1 clear QN");
        chk(s7_q, 1'b1, "DFFE_X1 clear"); chk(s7_qn, 1'b0, "DFFE_X1 clear QN");
        chk(s8_q, 1'b1, "SDFF_X1 clear"); chk(s8_qn, 1'b0, "SDFF_X1 clear QN");
        chk(s9_q, 1'b1, "SDFF_X2 clear"); chk(s9_qn, 1'b0, "SDFF_X2 clear QN");
        chk(s10_q, 1'b0, "SDFFR_X1 clear"); chk(s10_qn, 1'b1, "SDFFR_X1 clear QN");
        chk(s11_q, 1'b0, "SDFFR_X2 clear"); chk(s11_qn, 1'b1, "SDFFR_X2 clear QN");
        chk(s12_q, 1'b1, "SDFFS_X1 clear"); chk(s12_qn, 1'b0, "SDFFS_X1 clear QN");
        tick;   // clear holds through a clock
        chk(s0_q, 1'b1, "DFF_X1 clear held");
        chk(s1_q, 1'b1, "DFF_X2 clear held");
        chk(s2_q, 1'b0, "DFFR_X1 clear held");
        chk(s3_q, 1'b0, "DFFR_X2 clear held");
        chk(s4_q, 1'b1, "DFFS_X1 clear held");
        chk(s5_q, 1'b1, "DFFS_X2 clear held");
        chk(s6_q, 1'b0, "DFFRS_X1 clear held");
        chk(s7_q, 1'b1, "DFFE_X1 clear held");
        chk(s8_q, 1'b1, "SDFF_X1 clear held");
        chk(s9_q, 1'b1, "SDFF_X2 clear held");
        chk(s10_q, 1'b0, "SDFFR_X1 clear held");
        chk(s11_q, 1'b0, "SDFFR_X2 clear held");
        chk(s12_q, 1'b1, "SDFFS_X1 clear held");
        rn = 1; d = 0; tick; sn = 0; #1;   // preset
        chk(s0_q, 1'b0, "DFF_X1 preset");
        chk(s1_q, 1'b0, "DFF_X2 preset");
        chk(s2_q, 1'b0, "DFFR_X1 preset");
        chk(s3_q, 1'b0, "DFFR_X2 preset");
        chk(s4_q, 1'b1, "DFFS_X1 preset");
        chk(s5_q, 1'b1, "DFFS_X2 preset");
        chk(s6_q, 1'b1, "DFFRS_X1 preset");
        chk(s7_q, 1'b0, "DFFE_X1 preset");
        chk(s8_q, 1'b0, "SDFF_X1 preset");
        chk(s9_q, 1'b0, "SDFF_X2 preset");
        chk(s10_q, 1'b0, "SDFFR_X1 preset");
        chk(s11_q, 1'b0, "SDFFR_X2 preset");
        chk(s12_q, 1'b1, "SDFFS_X1 preset");
        rn = 0; #1;   // both: Q and QN low where the cell has both pins
        chk(s6_q, 1'b0, "DFFRS_X1 clear+preset"); chk(s6_qn, 1'b0, "DFFRS_X1 clear+preset QN");
        rn = 1; sn = 1; d = 0; tick;
        // ---- latches: transparent, then closed
        ck = 0; e = 1; d = 1; #1;
        cells = cells + 1;
        chk(s13_q, 1'b1, "DLH_X1 open");
        cells = cells + 1;
        chk(s14_q, 1'b1, "DLH_X2 open");
        cells = cells + 1;
        e = 0; #1; d = 0; #1;
        chk(s13_q, 1'b1, "DLH_X1 after e=0");
        chk(s14_q, 1'b1, "DLH_X2 after e=0");
        chk(s15_q, 1'b0, "DLL_X1 after e=0");
        e = 1; #1; d = 1; #1;
        chk(s13_q, 1'b1, "DLH_X1 after e=1");
        chk(s14_q, 1'b1, "DLH_X2 after e=1");
        chk(s15_q, 1'b0, "DLL_X1 after e=1");
        // ---- clock gates: enable sampled while the clock is low, no glitch
        ck = 0; se = 0; e = 1; #1; ck = 1; #1;
        cells = cells + 1; chk(s16_gck, 1'b1, "CLKGATE_X1 enabled");
        cells = cells + 1; chk(s17_gck, 1'b1, "CLKGATE_X2 enabled");
        cells = cells + 1; chk(s18_gck, 1'b1, "CLKGATE_X4 enabled");
        e = 0; #1;   // dropping the enable while the clock is high does not cut the pulse
        chk(s16_gck, 1'b1, "CLKGATE_X1 no glitch");
        chk(s17_gck, 1'b1, "CLKGATE_X2 no glitch");
        chk(s18_gck, 1'b1, "CLKGATE_X4 no glitch");
        ck = 0; #1; ck = 1; #1;
        chk(s16_gck, 1'b0, "CLKGATE_X1 gated");
        chk(s17_gck, 1'b0, "CLKGATE_X2 gated");
        chk(s18_gck, 1'b0, "CLKGATE_X4 gated");
        e = 1; #1;   // raising it while the clock is high does not start one
        chk(s16_gck, 1'b0, "CLKGATE_X1 no late pulse");
        chk(s17_gck, 1'b0, "CLKGATE_X2 no late pulse");
        chk(s18_gck, 1'b0, "CLKGATE_X4 no late pulse");
        ck = 0; e = 0; se = 1; #1; ck = 1; #1;   // the test pin enables too
        chk(s16_gck, 1'b1, "CLKGATE_X1 test enable");
        chk(s17_gck, 1'b1, "CLKGATE_X2 test enable");
        chk(s18_gck, 1'b1, "CLKGATE_X4 test enable");
        $display("mini45: %0d cells checked, %0d errors", cells, errors);
        $finish;
    end
endmodule
